const [active, setActive] = useState<string | null>(null);

<SankeyChart
  nodes={sources}
  links={flows}
  activeId={active}
  onActiveIdChange={setActive}
>
  <SankeyChart.Links />
  <SankeyChart.Nodes />
  <SankeyChart.Labels />
  <SankeyChart.Tooltip />
</SankeyChart>

// At most six bars in any column, the bucket included.
<SankeyChart nodes={sources} links={flows} collapse={{ maxPerColumn: 6 }}>
  <SankeyChart.Links />
  <SankeyChart.Nodes />
  <SankeyChart.Labels />
</SankeyChart>

// Or by share: anything under 2% of its own column goes in.
<SankeyChart
  nodes={sources}
  links={flows}
  collapse={{ minShare: 0.02, label: 'Everything else' }}
>
  …
</SankeyChart>

const [dropped, setDropped] = useState(0);

<SankeyChart nodes={sources} links={flows} onDropLinks={setDropped}>
  <SankeyChart.Links />
  <SankeyChart.Nodes />
  <SankeyChart.Labels />
</SankeyChart>

{dropped > 0 ? (
  <Text size="xs" muted>{`${dropped} rows could not be drawn`}</Text>
) : null}
